import { z } from "zod";

// userId is min(1), not uuid(), to match cart's createCartSchema. Guest
// checkout mints client-side ids that carts already accept, so orders has
// to accept the same set — a stricter rule here would reject a userId that
// successfully created the very cart being ordered from. cartId stays
// uuid(): that one is always server-generated by cart.
export const createOrderSchema = z.object({
  userId: z.string().min(1),
  cartId: z.string().uuid(),
});

export const orderIdParamSchema = z.object({
  id: z.string().uuid(),
});

export type CreateOrderInput = z.infer<typeof createOrderSchema>;
